(()=>{const path='M12 21C10 19.2 2 13.7 2 7.8C2 4.6 4.3 2.8 7 2.8C9.2 2.8 10.8 4 12 5.8C13.2 4 14.8 2.8 17 2.8C19.7 2.8 22 4.6 22 7.8C22 13.7 14 19.2 12 21Z';const units=hp=>Math.max(0,Math.min(40,Math.ceil((Number(hp)||0)/2.5)));function render(hp){const n=units(hp);return Array.from({length:20},(_,i)=>{const fill=Math.max(0,Math.min(2,n-i*2))*50;return `<svg class="hpHeart" viewBox="0 0 24 24" aria-hidden="true" data-fill="${fill}"><path d="${path}" fill="#21332bd9"/><g style="clip-path:inset(0 ${100-fill}% 0 0)"><path d="${path}" fill="#e36865"/><path d="M5 7.5C5 5.8 7 5 8.5 6" fill="none" stroke="#ffd5bc" stroke-width="1.4" stroke-linecap="round" opacity=".65"/></g><path d="${path}" fill="none" stroke="#582d2b" stroke-width="1.1" stroke-linejoin="round"/></svg>`;}).join('');}window.SurvivalHearts={units,render,update(el,hp){const n=units(hp);if(el.dataset.units===String(n))return;el.dataset.units=n;el.innerHTML=render(hp);el.setAttribute('aria-label',`体力 ${n/2} / 20 ハート`);}};})();
